# SaleHop update: photos + notes on spotted sales, verified by location
# - Browse's list view now shows spotted sales too (schema-v10's
#   crowdsourced "spot a sale while driving by" pins), not just the map --
#   a new dashed card labeled "Spotted Sale" with an Unconfirmed/Confirmed
#   badge, distance, and photo/note counts. Tapping one (from the list OR
#   a map pin -- map pins open this now instead of a small popup) opens a
#   detail sheet showing whatever's been added so far.
# - From that detail sheet, ANYONE who can prove they're actually near the
#   sale can add a photo and/or a short note, at any time -- not just
#   whoever first reported or confirmed it -- and it shows up immediately,
#   no admin approval needed.
# - "Proving you're there" works two ways: the photo's own location data
#   (read from its EXIF -- most phone cameras save this automatically), or
#   the visitor's live browser location, checked server-side against the
#   same radius setting /admin already uses for confirming a spotted sale.
#   If neither is available or close enough, the upload is flat-out
#   rejected -- there's no "unverified" fallback that stores it anyway.
# - Before a photo is ever stored publicly, ALL of its metadata (including
#   that same location data) is stripped out server-side. If stripping
#   ever fails for any reason, the upload is rejected rather than risk
#   storing a photo that still leaks where it was taken. Only plain JPEG
#   photos are accepted for now (the most common camera-roll format).
# - A still-unconfirmed spotted sale gets auto-confirmed the moment it
#   gets a verified photo/note contribution, using that same proof of
#   presence -- on top of the existing crowd-report and drive-and-confirm
#   ways a spot can already become confirmed.
# - New /admin capability: every spotted sale's photos and notes are shown
#   in the Spotted Sales section, each with its own Remove button, so you
#   can take down an individual photo or note without rejecting/deleting
#   the whole reported sale.
# - New file: supabase/schema-v11-spotted-sale-details.sql (two new
#   columns on `spotted_sales`, plus a new `spotted-sale-photos` storage
#   bucket -- run this once in the Supabase SQL Editor; safe to run even
#   though it comes after schema-v10, which must be run first if you
#   haven't already). New files: components/SpottedSaleCard.js,
#   components/SpottedSaleSheet.js, and the new
#   app/api/spotted-sales/[id]/(route.js|photos/route.js) endpoints.
#   Touches lib/format.js, app/api/spotted-sales/route.js,
#   app/api/admin/spotted-sales/(route.js|[id]/route.js),
#   components/(LeafletMap|MapScreen|BrowseScreen|AppShell).js,
#   app/admin/page.js, and app/globals.css.
# - NEW NPM PACKAGES: this feature needs two small libraries this project
#   hasn't used before -- "exifr" (reads a photo's location data so it can
#   be checked) and "piexifjs" (strips that same data back out before the
#   photo is stored). This script installs them for you below; if that
#   step fails for any reason, run this yourself from the project folder
#   before deploying:
#     npm install exifr piexifjs

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)

