"@
[System.IO.File]::WriteAllBytes("app/globals.css", [Convert]::FromBase64String($b64_globalscss))
Write-Host "Wrote app/globals.css"

$checkFiles = @(
    "supabase/schema-v11-spotted-sale-details.sql",
    "lib/format.js",
    "app/api/spotted-sales/route.js",
    "app/api/spotted-sales/[id]/route.js",
    "app/api/spotted-sales/[id]/photos/route.js",
    "app/api/admin/spotted-sales/route.js",
    "app/api/admin/spotted-sales/[id]/route.js",
    "components/SpottedSaleCard.js",
    "components/SpottedSaleSheet.js",
    "components/LeafletMap.js",
    "components/MapScreen.js",
    "components/BrowseScreen.js",
    "components/AppShell.js",
    "app/admin/page.js",
    "app/globals.css"
)
$missing = $checkFiles | Where-Object { -not (Test-Path -LiteralPath $_) }
if ($missing) {
    Write-Host "ERROR: the following files did not get written:" -ForegroundColor Red
    $missing | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
    exit 1
}
Write-Host ""
Write-Host "All files written successfully." -ForegroundColor Green
Write-Host ""

Write-Host "Installing new npm packages (exifr, piexifjs)..." -ForegroundColor Cyan
npm install exifr piexifjs
if ($LASTEXITCODE -ne 0) {
    Write-Host "WARNING: npm install failed. Run 'npm install exifr piexifjs' yourself before deploying, or the new photo-upload feature will break." -ForegroundColor Yellow
} else {
    Write-Host "Packages installed." -ForegroundColor Green
}
Write-Host ""

Write-Host "IMPORTANT: this feature needs a database migration. Open your Supabase" -ForegroundColor Yellow
Write-Host "project's SQL Editor and run the contents of:" -ForegroundColor Yellow
Write-Host "  supabase/schema-v11-spotted-sale-details.sql" -ForegroundColor Yellow
Write-Host "(after schema-v10-spotted-sales.sql, if you haven't run that one yet either)" -ForegroundColor Yellow
Write-Host "before (or right after) you deploy this, or the new photo/note feature won't work yet." -ForegroundColor Yellow
Write-Host ""

git status

Write-Host ""
$answer = Read-Host "Commit and push these changes now? (Y/N)"
if ($answer -eq "Y" -or $answer -eq "y") {
    git add -A
    if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: git add failed." -ForegroundColor Red; exit 1 }

    $commitMessage = @"
Add photos and notes to spotted sales, verified by photo/live location

Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01146L7oDTraxR2XyGhaGyrm
"@

    $commitMsgFile = [System.IO.Path]::GetTempFileName()
    [System.IO.File]::WriteAllText($commitMsgFile, $commitMessage)
    git commit -F $commitMsgFile
    $commitExitCode = $LASTEXITCODE
    Remove-Item $commitMsgFile -ErrorAction SilentlyContinue
    if ($commitExitCode -ne 0) { Write-Host "ERROR: git commit failed." -ForegroundColor Red; exit 1 }

    git push
    if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: git push failed." -ForegroundColor Red; exit 1 }

    Write-Host ""
    Write-Host "Done! Changes committed and pushed. Vercel should start deploying shortly." -ForegroundColor Green
    Write-Host "Don't forget to run the SQL migration in Supabase if you haven't yet." -ForegroundColor Yellow
} else {
    Write-Host "Skipped commit/push. Your files were updated locally but not committed." -ForegroundColor Yellow
}
